function model(p) {
  // Two carts on a frictionless track. Cart 1 moves toward cart 2, which is at rest; they collide once with a chosen
  // elasticity (1 = perfectly elastic, 0 = they stick). Momentum is conserved in every case; kinetic energy only when
  // elastic. Positions over time come from the velocities before and after the one collision.
  const ratio = Math.max(0.25, Math.min(4, Math.round(p.massRatio * 4) / 4));
  const e = Math.max(0, Math.min(1, Math.round(p.elasticity * 10) / 10));
  const v1 = Math.max(1, Math.min(5, Math.round(p.speed * 2) / 2));
  const m1 = 1, m2 = ratio, v2 = 0, x1 = 1, x2 = 6, L1 = 1, L2 = 0.8 + 0.4 * Math.sqrt(ratio); // cart lengths, m
  const tc = (x2 - L2 / 2 - (x1 + L1 / 2)) / v1; // the gap closes at speed v1
  const u1 = ((m1 - e * m2) * v1 + (1 + e) * m2 * v2) / (m1 + m2), u2 = ((m2 - e * m1) * v2 + (1 + e) * m1 * v1) / (m1 + m2);
  const pBefore = m1 * v1 + m2 * v2, pAfter = m1 * u1 + m2 * u2;
  const kBefore = 0.5 * m1 * v1 * v1 + 0.5 * m2 * v2 * v2, kAfter = 0.5 * m1 * u1 * u1 + 0.5 * m2 * u2 * u2;
  const mu = m1 * m2 / (m1 + m2), lossFormula = 0.5 * mu * (1 - e * e) * (v1 - v2) ** 2;
  const duration = 8, fps = 60, series = [];
  for (let i = 0; i <= duration * fps; i++) {
    const t = i / fps, after = t >= tc;
    series.push({ t: +t.toFixed(3), x1: +(after ? x1 + v1 * tc + u1 * (t - tc) : x1 + v1 * t).toFixed(4), x2: +(after ? x2 + u2 * (t - tc) : x2).toFixed(4), v1: after ? +u1.toFixed(4) : v1, v2: after ? +u2.toFixed(4) : v2,
      p: +(after ? pAfter : pBefore).toFixed(4), k: +(after ? kAfter : kBefore).toFixed(4) });
  }
  const kind = e === 1 ? 'elastic' : e === 0 ? 'perfectly inelastic (they stick)' : 'partly elastic';
  const fmt = v => (Math.round(v * 100) / 100).toFixed(2);
  const sign = v => (v >= 0 ? '+' : '−') + fmt(Math.abs(v));
  const whatHappens = u1 < -1e-9 ? 'Cart 1 bounces back at ' + fmt(-u1) + ' m/s' : u1 > 1e-9 ? 'Cart 1 keeps going at ' + fmt(u1) + ' m/s' : 'Cart 1 stops dead';
  const steps = [
    { id: 'approach', t: 0, title: 'Cart 1 (' + m1 + ' kg) at ' + fmt(v1) + ' m/s, cart 2 (' + ratio + ' kg) at rest', note: 'Momentum ' + fmt(pBefore) + ' kg·m/s, kinetic energy ' + fmt(kBefore) + ' J. Watch which of the two survives the collision.' },
    { id: 'hit', t: tc, title: 'Collision, ' + kind, note: whatHappens + '; cart 2 moves off at ' + fmt(u2) + ' m/s. Momentum after: ' + fmt(pAfter) + ' kg·m/s, the same. Energy after: ' + fmt(kAfter) + ' J' + (e === 1 ? ', the same.' : ', ' + fmt(kBefore - kAfter) + ' J went into heat, sound and dents.') },
    { id: 'after', t: Math.min(duration - 2.5, tc + 2.5), title: 'After', note: ratio > 1 && e === 1 ? 'A light cart hitting a heavy one bounces back; the heavy one barely moves.' : ratio < 1 && e === 1 ? 'A heavy cart hitting a light one keeps going; the light one flies off faster than the heavy one came in.' : e === 0 ? 'Stuck together they share the momentum, so they move at ' + fmt(u2) + ' m/s, and the lost energy is the most any collision can lose.' : 'Equal masses and elastic: they swap velocities exactly.' },
    { id: 'sowhat', t: duration - 1.5, title: 'So what', note: 'Momentum is the bookkeeping that always balances; energy is the one that leaks. The elasticity is the leak.' }
  ];
  const summary = 'Mass ratio ' + ratio + ', elasticity ' + e + ', ' + fmt(v1) + ' m/s: after the hit cart 1 ' + sign(u1) + ' m/s, cart 2 ' + sign(u2) + ' m/s; momentum ' + fmt(pBefore) + ' → ' + fmt(pAfter) + ', energy ' + fmt(kBefore) + ' → ' + fmt(kAfter) + ' J.';
  return { m1, m2, v1, v2, e, ratio, x1, x2, L1, L2, tc: +tc.toFixed(4), u1: +u1.toFixed(4), u2: +u2.toFixed(4), pBefore: +pBefore.toFixed(4), pAfter: +pAfter.toFixed(4), kBefore: +kBefore.toFixed(4), kAfter: +kAfter.toFixed(4), loss: +(kBefore - kAfter).toFixed(4), lossFormula: +lossFormula.toFixed(4), kind, series, steps, duration, markers: steps.map(s => s.t), summary };
}

