function check(p) {
  const m = model(p);
  // Momentum is conserved exactly; kinetic energy is conserved only when elastic, and the loss matches the closed form
  const momentumOk = Math.abs(m.pAfter - m.pBefore) < 1e-6;
  const energyOk = m.e === 1 ? Math.abs(m.kAfter - m.kBefore) < 1e-6 : m.kAfter < m.kBefore - 1e-9;
  const lossOk = Math.abs(m.loss - m.lossFormula) < 1e-3;
  // Sticking means a shared velocity; equal masses and elastic means a swap; the positions never pass through each other
  const stickOk = m.e !== 0 || Math.abs(m.u1 - m.u2) < 1e-6;
  const swapOk = !(m.e === 1 && m.ratio === 1) || (Math.abs(m.u1 - m.v2) < 1e-6 && Math.abs(m.u2 - m.v1) < 1e-6);
  const noPass = m.series.every(s => s.x1 + m.L1 / 2 <= s.x2 - m.L2 / 2 + 1e-3);
  const seriesOk = m.series.every(s => Math.abs(s.p - m.pBefore) < 1e-6) && m.series[0].t === 0 && m.series.length === m.duration * 60 + 1;
  const pass = momentumOk && energyOk && lossOk && stickOk && swapOk && noPass && seriesOk;
  return {
    pass,
    detail: 'Momentum ' + m.pBefore.toFixed(2) + ' → ' + m.pAfter.toFixed(2) + ' kg·m/s' + (momentumOk ? '' : ' (not conserved)') + '; energy ' + m.kBefore.toFixed(2) + ' → ' + m.kAfter.toFixed(2) + ' J, loss ' + m.loss.toFixed(2) + ' J vs formula ' + m.lossFormula.toFixed(2) + (lossOk ? '' : ' (mismatch)') +
      '; ' + (m.e === 0 ? 'stuck together' + (stickOk ? '' : ' (but velocities differ)') : m.e === 1 && m.ratio === 1 ? 'velocities swapped' + (swapOk ? '' : ' (they did not)') : 'carts never overlap' + (noPass ? '' : ' (they do)')) + '.'
  };
}
